import json, os, csv

for f in ['acquirer_countries.csv','merchant_category_codes.csv','payments.csv','merchant_data.json','fees.json','payments-readme.md']:
    print('\n===',f,os.path.getsize(f),'===')
    if f.endswith('.csv'):
        with open(f, newline='', encoding='utf-8') as fh:
            r=csv.reader(fh)
            rows=[next(r) for _ in range(6)]
        for row in rows: print(row)
    elif f.endswith('.json'):
        with open(f, encoding='utf-8') as fh:
            data=json.load(fh)
        print(type(data), len(data) if hasattr(data,'__len__') else '')
        if isinstance(data,list):
            print(json.dumps(data[:3],indent=2)[:3000])
        elif isinstance(data,dict):
            print(list(data.keys())[:20])
            print(json.dumps(data,indent=2)[:3000])
    else:
        print(open(f, encoding='utf-8').read()[:2000])
